code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sep_rows = [r for r in range(h) if all(v == grid[r][0] and v != bg for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] and grid[0][c] != bg for r in range(h))]
    def chunks(n, cuts):
        out=[]; start=0
        for x in cuts:
            if start < x: out.append((start,x))
            start=x+1
        if start<n: out.append((start,n))
        return out
    row_groups=chunks(h,sep_rows)
    col_groups=chunks(w,sep_cols)
    tiles=[]
    for ri,(r0,r1) in enumerate(row_groups):
        for ci,(c0,c1) in enumerate(col_groups):
            score=sum(grid[r][c] != bg for r in range(r0,r1) for c in range(c0,c1))
            tiles.append((score,r0,r1,c0,c1))
    _,r0,r1,c0,c1=max(tiles)
    pattern=[[grid[r][c] for c in range(c0,c1)] for r in range(r0,r1)]
    out=[row[:] for row in grid]
    for a,b in row_groups:
        for x,y in col_groups:
            if b-a != len(pattern) or y-x != len(pattern[0]):
                continue
            for i in range(b-a):
                for j in range(y-x):
                    out[a+i][x+j]=pattern[i][j]
    return out
